const errors = [];
const metadata = $json.metadata && typeof $json.metadata === 'object' && !Array.isArray($json.metadata)
  ? $json.metadata
  : {};

if ($json.route !== 'novel.metadata.created') {
  errors.push('Invalid route: expected novel.metadata.created.');
}
if (!$json.metadata || typeof $json.metadata !== 'object' || Array.isArray($json.metadata)) {
  errors.push('Invalid metadata: expected an object.');
}

const canonicalMetadata = {
  novel_uuid: String(metadata.novel_uuid ?? metadata.uuid ?? '').trim(),
  novel_slug: String(metadata.novel_slug ?? metadata.slug ?? '').trim(),
  novel_title: String(metadata.novel_title ?? metadata.title ?? '').trim(),
  novel_genre: String(metadata.novel_genre ?? metadata.genre ?? '').trim(),
  created_at: String(metadata.created_at ?? '').trim(),
  created_by: String(metadata.created_by ?? 'Novel Studio').trim(),
};

if (!canonicalMetadata.novel_uuid) errors.push('metadata.novel_uuid is required.');
if (!canonicalMetadata.novel_slug) errors.push('metadata.novel_slug is required.');
if (!canonicalMetadata.novel_title) errors.push('metadata.novel_title is required.');
if (!canonicalMetadata.created_at || Number.isNaN(Date.parse(canonicalMetadata.created_at))) {
  errors.push('metadata.created_at must be a valid ISO 8601 timestamp.');
}
if (!canonicalMetadata.created_by) errors.push('metadata.created_by is required.');

return [{
  json: {
    ...$json,
    metadata_valid: errors.length === 0,
    validation_errors: errors,
    canonical_metadata: canonicalMetadata,
  },
}];

const folderNames = [
  'Novel/',
  'Novel/01_Source/',
  'Novel/02_Chapters/',
  'Novel/03_Canon/',
  'Novel/04_Characters/',
  'Novel/05_World/',
  'Novel/06_Outline/',
  'Novel/07_Assets/',
  'Novel/08_Publish/',
  'Novel/09_Backup/',
];

return [{
  json: {
    ...$json,
    generated_folder_manifest: folderNames.map((path, index) => ({
      order: index,
      path,
      status: 'planned',
    })),
  },
}];

const files = [
  { path: 'Novel/README.md', purpose: 'Workspace overview' },
  { path: 'Novel/01_Source/source-notes.md', purpose: 'Raw source notes' },
  { path: 'Novel/03_Canon/novel-metadata.json', purpose: 'Canonical novel metadata' },
  { path: 'Novel/03_Canon/canon.md', purpose: 'Canonical story facts' },
  { path: 'Novel/04_Characters/characters.json', purpose: 'Character manifest' },
  { path: 'Novel/05_World/world.json', purpose: 'World-building manifest' },
  { path: 'Novel/06_Outline/outline.md', purpose: 'Novel outline' },
  { path: 'Novel/08_Publish/publish-manifest.json', purpose: 'Publishing manifest' },
  { path: 'Novel/09_Backup/backup-manifest.json', purpose: 'Backup manifest' },
];

return [{
  json: {
    ...$json,
    generated_file_manifest: files.map((file) => ({
      ...file,
      status: 'planned',
    })),
  },
}];

function uuidHelper() {
  let timestamp = Date.now();
  let highResolution = typeof performance !== 'undefined' && typeof performance.now === 'function'
    ? Math.floor(performance.now() * 1000)
    : 0;

  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (token) => {
    let random = Math.random() * 16;
    if (timestamp > 0) {
      random = (timestamp + random) % 16 | 0;
      timestamp = Math.floor(timestamp / 16);
    } else {
      random = (highResolution + random) % 16 | 0;
      highResolution = Math.floor(highResolution / 16);
    }
    return (token === 'x' ? random : (random & 0x3) | 0x8).toString(16);
  });
}

const metadata = $json.canonical_metadata ?? {};
const safeName = metadata.novel_slug || metadata.novel_uuid || 'unassigned-novel';
const isReady = $json.metadata_valid === true;

return [{
  json: {
    ...$json,
    workspace: {
      workspace_uuid: uuidHelper(),
      workspace_name: `${safeName}-workspace`,
      folder_manifest: $json.generated_folder_manifest,
      file_manifest: $json.generated_file_manifest,
      status: isReady ? 'ready' : 'invalid',
      next_workflow: isReady ? 'WF-003 P02' : '',
    },
  },
}];

const workspace = $json.workspace ?? {};

return [{
  json: {
    route: $json.metadata_valid ? 'novel.workspace.provisioned' : 'novel.workspace.invalid',
    workspace_uuid: workspace.workspace_uuid ?? '',
    workspace_name: workspace.workspace_name ?? '',
    folder_manifest: workspace.folder_manifest ?? [],
    file_manifest: workspace.file_manifest ?? [],
    status: workspace.status ?? 'invalid',
    next_workflow: workspace.next_workflow ?? '',
    validation_errors: $json.validation_errors ?? [],
  },
}];
